From 06005a871a859e2570dba2ece3f2e2cb58421a2c Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 22:43:52 +0100
Subject: [PATCH] startkde: refuse to start when a graphical session is already
 running

systemd allows only one graphical-session.target per user, so a second
login for the same user showed a black screen and, when it gave up, also
stopped the running session. Now check first and exit with a message.

BUG: 464045
---
 startkde/startplasma.cpp | 29 +++++++++++++++++++++++++++++
 1 file changed, 29 insertions(+)

diff --git a/startkde/startplasma.cpp b/startkde/startplasma.cpp
index 9cda0be1e5..be4194dea2 100644
--- a/startkde/startplasma.cpp
+++ b/startkde/startplasma.cpp
@@ -627,6 +627,30 @@ bool useSystemdBoot()
     return hasSystemdService(QStringLiteral("xdg-desktop-autostart.target"));
 }

+bool isGraphicalSessionRunning()
+{
+    auto msg = QDBusMessage::createMethodCall(QStringLiteral("org.freedesktop.systemd1"),
+                                              QStringLiteral("/org/freedesktop/systemd1"),
+                                              QStringLiteral("org.freedesktop.systemd1.Manager"),
+                                              QStringLiteral("GetUnit"));
+    msg << QStringLiteral("graphical-session.target");
+    const QDBusReply<QDBusObjectPath> unit = QDBusConnection::sessionBus().call(msg);
+    if (!unit.isValid()) {
+        return false;
+    }
+    QDBusInterface properties(QStringLiteral("org.freedesktop.systemd1"),
+                              unit.value().path(),
+                              QStringLiteral("org.freedesktop.DBus.Properties"),
+                              QDBusConnection::sessionBus());
+    const QDBusReply<QDBusVariant> state =
+        properties.call(QStringLiteral("Get"), QStringLiteral("org.freedesktop.systemd1.Unit"), QStringLiteral("ActiveState"));
+    if (!state.isValid()) {
+        return false;
+    }
+    const QString activeState = state.value().variant().toString();
+    return activeState == QLatin1String("active") || activeState == QLatin1String("activating") || activeState == QLatin1String("reloading");
+}
+
 void startKSplashViaSystemd()
 {
     const KConfig cfg(QStringLiteral("ksplashrc"));
@@ -849,6 +873,11 @@ int main(int argc, char **argv)
         out << "startplasmacompositor: Could not start D-Bus. Can you call qdbus?\n";
         return 1;
     }
+    // systemd allows only one graphical session per user
+    if (useSystemdBoot() && isGraphicalSessionRunning()) {
+        messageBox(QStringLiteral("startplasma-wayland: A graphical session is already running for this user. Log out of it before starting a new one.\n"));
+        return 1;
+    }
     setupPlasmaEnvironment();
     runStartupConfig();
     qputenv("XDG_SESSION_TYPE", "wayland");
-- 
